INSERT INTO `{{PREFIX}}category_description` (`category_id`, `language_id`, `name`, `description`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(5001, 2, 'Посуд', '<p>«Крістал» здає в оренду посуд для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 10 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду посуду</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда посуду у Львові — від 10 грн | Крістал', 'Оренда посуду для весілля, банкетів і фуршетів у Львові. Ціни від 10 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, посуд, mock'),
(5021, 2, 'Тарілки', '<p>«Крістал» здає в оренду тарілки для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 11 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду тарілок</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда тарілок у Львові — від 11 грн | Крістал', 'Оренда тарілок для весілля, банкетів і фуршетів у Львові. Ціни від 11 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, тарілки, mock'),
(5022, 2, 'Салатниці та супниці', '<p>«Крістал» здає в оренду салатниці та супниці для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 10 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду салатниць і супниць</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда салатниць і супниць у Львові — від 10 грн | Крістал', 'Оренда салатниць і супниць для весілля, банкетів і фуршетів у Львові. Ціни від 10 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, салатниці та супниці, mock'),
(5023, 2, 'Блюда для подачі', '<p>«Крістал» здає в оренду блюда для подачі для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 28 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду блюд для подачі</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда блюд для подачі у Львові — від 28 грн | Крістал', 'Оренда блюд для подачі для весілля, банкетів і фуршетів у Львові. Ціни від 28 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, блюда для подачі, mock'),
(5024, 2, 'Ексклюзивний посуд', '<p>«Крістал» здає в оренду ексклюзивний посуд для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 22 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду ексклюзивного посуду</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда ексклюзивного посуду у Львові — від 22 грн | Крістал', 'Оренда ексклюзивного посуду для весілля, банкетів і фуршетів у Львові. Ціни від 22 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, ексклюзивний посуд, mock'),
(5002, 2, 'Столові прибори', '<p>«Крістал» здає в оренду столові прибори для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 5 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду столових приборів</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда столових приборів у Львові — від 5 грн | Крістал', 'Оренда столових приборів для весілля, банкетів і фуршетів у Львові. Ціни від 5 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, столові прибори, mock'),
(5025, 2, 'Виделки', '<p>«Крістал» здає в оренду виделки для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів у Львові та області. Ціна — від 6 грн за одиницю на добу, а для великих подій діють знижки за обсяг.</p><h2>Як замовити оренду виделок</h2><p>Надішліть дату, кількість гостей і меню — менеджер розрахує, скільки і яких позицій потрібно, і підтвердить наявність на складі. Доставляємо, забираємо після події, посуд повертається без миття (послуга входить у вартість — уточнюється).</p><h2>Що важливо знати</h2><ul><li>Мінімальне замовлення вказане в картці кожного товару.</li><li>У разі бою або втрати сплачується вартість відшкодування з картки товару.</li><li>Бронювання на дату — після передоплати.</li></ul><p><em>Тексти, ціни й умови на цій сторінці — тестові (мок-дані).</em></p>', 'Оренда виделок у Львові — від 6 грн | Крістал', 'Оренда виделок для весілля, банкетів і фуршетів у Львові. Ціни від 6 грн за добу, доставка і вивезення, розрахунок кількості за 15 хвилин.', 'оренда, виделки, mock'),
