INSERT INTO `{{PREFIX}}product_description` (`product_id`, `language_id`, `name`, `description`, `description_excerpt`, `description_add`, `tag`, `meta_title`, `meta_description`, `meta_keyword`) VALUES
(50001, 2, 'Тарілка обідня біла 27 см', '<p>Тарілка обідня біла 27 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 27 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 27 см</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 14 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 120 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Порцеляна, Ø 27 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка обідня біла 27 см — оренда у Львові, 14 грн | Крістал', 'Тарілка обідня біла 27 см в оренду: 14 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
(50002, 2, 'Тарілка закусочна біла 21 см', '<p>Тарілка закусочна біла 21 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 21 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 21 см</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 12 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 100 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Порцеляна, Ø 21 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка закусочна біла 21 см — оренда у Львові, 12 грн | Крістал', 'Тарілка закусочна біла 21 см в оренду: 12 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
(50003, 2, 'Тарілка десертна 19 см', '<p>Тарілка десертна 19 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 19 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 19 см</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 11 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 90 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Порцеляна, Ø 19 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка десертна 19 см — оренда у Львові, 11 грн | Крістал', 'Тарілка десертна 19 см в оренду: 11 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
(50004, 2, 'Тарілка глибока 23 см', '<p>Тарілка глибока 23 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 23 см, 450 мл, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 23 см</li><li>Об''єм: 450 мл</li><li>Колір: Білий</li><li>Серія / стиль: Classic</li></ul><p>Ціна 14 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 120 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Порцеляна, Ø 23 см, 450 мл, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка глибока 23 см — оренда у Львові, 14 грн | Крістал', 'Тарілка глибока 23 см в оренду: 14 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
(50005, 2, 'Підставна тарілка золота 33 см', '<p>Підставна тарілка золота 33 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Скло з напиленням, Ø 33 см, Золото.</p><ul><li>Матеріал: Скло з напиленням</li><li>Розмір: Ø 33 см</li><li>Колір: Золото</li><li>Серія / стиль: Royal</li></ul><p>Ціна 35 грн — за 1 шт. на добу. Мінімальне замовлення — 10 шт. Відшкодування при бутті або втраті — 350 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Скло з напиленням, Ø 33 см, Золото.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Підставна тарілка золота 33 см — оренда у Львові, 35 грн | Крістал', 'Підставна тарілка золота 33 см в оренду: 35 грн (1 шт. на добу), мінімум 10 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
(50006, 2, 'Тарілка квадратна 26×26 см', '<p>Тарілка квадратна 26×26 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, 26×26 см, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: 26×26 см</li><li>Колір: Білий</li><li>Серія / стиль: Modern</li></ul><p>Ціна 18 грн — за 1 шт. на добу. Мінімальне замовлення — 10 шт. Відшкодування при бутті або втраті — 180 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Порцеляна, 26×26 см, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, тарілки', 'Тарілка квадратна 26×26 см — оренда у Львові, 18 грн | Крістал', 'Тарілка квадратна 26×26 см в оренду: 18 грн (1 шт. на добу), мінімум 10 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
(50007, 2, 'Салатниця порційна 12 см', '<p>Салатниця порційна 12 см — для весілля, банкетів, фуршетів, корпоративів, кейтерингу та виїзних заходів. Порцеляна, Ø 12 см, 250 мл, Білий.</p><ul><li>Матеріал: Порцеляна</li><li>Розмір: Ø 12 см</li><li>Об''єм: 250 мл</li><li>Колір: Білий</li></ul><p>Ціна 10 грн — за 1 шт. на добу. Мінімальне замовлення — 20 шт. Відшкодування при бутті або втраті — 90 грн за одиницю.</p><p><em>Тестовий товар (мок-дані).</em></p>', 'Порцеляна, Ø 12 см, 250 мл, Білий.', 'ціна за 1 шт. на добу', 'оренда, посуд, салатниці та супниці', 'Салатниця порційна 12 см — оренда у Львові, 10 грн | Крістал', 'Салатниця порційна 12 см в оренду: 10 грн (1 шт. на добу), мінімум 20 шт. Доставка по Львову, підбір кількості під вашу подію.', 'оренда, mock'),
