-- 3. Перевірка: жоден мок-ключ ЧПУ не зайнятий реальними сторінками
DROP TEMPORARY TABLE IF EXISTS `kristal_tmp_keyword`;
CREATE TEMPORARY TABLE `kristal_tmp_keyword` SELECT `keyword` FROM `{{PREFIX}}seo_url` LIMIT 0;
DELIMITER $$
BEGIN NOT ATOMIC
  DECLARE n INT DEFAULT 0;
  DECLARE taken TEXT DEFAULT '';
  DECLARE msg VARCHAR(128);
  SELECT COUNT(*), IFNULL(GROUP_CONCAT(s.`keyword` SEPARATOR ', '), '') INTO n, taken
    FROM `{{PREFIX}}seo_url` s JOIN `kristal_tmp_keyword` k ON k.`keyword` = s.`keyword`
   WHERE s.`store_id` = 0 AND s.`language_id` = 2;
  IF n > 0 THEN
    SET msg = LEFT(CONCAT('0001: SEO-ключі вже зайняті: ', taken), 128);
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
  END IF;
END$$
DELIMITER ;
DROP TEMPORARY TABLE IF EXISTS `kristal_tmp_keyword`;

-- 4. Сховати старі категорії (стан зберігається в {{PREFIX}}kristal_mock_backup один раз)
SELECT 'category', `category_id`, 'status', `status` FROM `{{PREFIX}}category`
 WHERE `category_id` NOT BETWEEN 5000 AND 5099;
SELECT 'category', `category_id`, 'top', `top` FROM `{{PREFIX}}category`
 WHERE `category_id` NOT BETWEEN 5000 AND 5099;
UPDATE `{{PREFIX}}category` SET `status` = 0, `top` = 0 WHERE `category_id` NOT BETWEEN 5000 AND 5099;

